def _get_class_from_global_namespace(global_ns, class_name):
    if class_name in global_ns:
        return global_ns[class_name]
    for module_name, module in global_ns.items():
        if hasattr(module, class_name):
            return getattr(module, class_name)
    raise ImportError("Unable to find class %s" % class_name)

